// src/api/tmdbApi.js

import axios from "axios";

const TMDB_API_KEY = "b56be59cfcfc26fbad50e51fb6341736"; // 🔑 실제 TMDB API 키를 입력하세요.
const BASE_URL = "https://api.themoviedb.org/3";
const IMAGE_BASE_URL = "https://image.tmdb.org/t/p/w780";

/**
 * TMDB에서 정확한 영화 포스터를 가져오는 고도화된 함수 (v3)
 * @param {string} title - KOFIC 제공 영화 제목 (국문)
 * @param {string} year - KOFIC 제공 개봉 연도 (YYYY)
 * @param {object} options - 추가 옵션 (movieNmEn 등)
 * @returns {string|null} 포스터 URL 또는 null
 */
export const getPosterFromTMDB = async (title, year, options = {}) => {
  try {
    // --- 1. 한글 제목과 영문 제목으로 각각 검색하여 후보군 확보 ---
    const koreanSearchPromise = axios.get(`${BASE_URL}/search/movie`, {
      params: {
        api_key: TMDB_API_KEY,
        query: title,
        language: "ko-KR",
        include_adult: false,
      },
    });

    const englishSearchPromise = options.movieNmEn
      ? axios.get(`${BASE_URL}/search/movie`, {
          params: {
            api_key: TMDB_API_KEY,
            query: options.movieNmEn,
            language: "ko-KR",
            include_adult: false,
          },
        })
      : Promise.resolve({ data: { results: [] } }); // 영문 제목 없으면 빈 결과 반환

    const [koreanResponse, englishResponse] = await Promise.all([
      koreanSearchPromise,
      englishSearchPromise,
    ]);

    // 두 검색 결과를 합치고 ID를 기준으로 중복 제거
    const allResults = [...koreanResponse.data.results, ...englishResponse.data.results];
    const uniqueResults = Array.from(new Map(allResults.map(movie => [movie.id, movie])).values());

    if (uniqueResults.length === 0) {
      console.warn(`[검색 결과 없음] "${title}"`);
      return null;
    }

    // --- 2. 확보된 후보군 중에서 가장 적합한 영화 선택 ---

    // 1순위: 개봉 연도가 정확히 일치하는 영화 찾기
    const perfectMatch = uniqueResults.find(
      (movie) => movie.release_date?.substring(0, 4) === year
    );

    if (perfectMatch) {
      console.log(`✅ [연도 일치] "${title}" → "${perfectMatch.title}" 포스터 선택`);
      return perfectMatch.poster_path ? `${IMAGE_BASE_URL}${perfectMatch.poster_path}` : null;
    }

    // 2순위: 연도 일치 영화가 없을 경우, 후보군 중에서 '인기도'가 가장 높은 영화 선택
    // (개봉일 정보가 다르거나 없는 경우를 위한 가장 합리적인 추측)
    if (uniqueResults.length > 0) {
        const mostPopular = uniqueResults.sort((a, b) => b.popularity - a.popularity)[0];
        console.log(`⚠️ [인기도 기반 선택] "${title}" (${year}) → "${mostPopular.title}" (${mostPopular.release_date}) 포스터 선택`);
        return mostPopular.poster_path ? `${IMAGE_BASE_URL}${mostPopular.poster_path}` : null;
    }

    // 모든 조건에서 찾지 못하면 null 반환
    return null;

  } catch (error) {
    console.error(`TMDB API 오류 (${title}):`, error.message);
    return null;
  }
};
